using System.ComponentModel;
using Runic.Application.Views;
using Runic.Navigation;

namespace Runic.Application.Testing.Tests;

// A NavigationRegion<TContent> slot generated by the Bridge build (W230-002 slice 2).
public sealed partial class NavShellWindow : RunicWindow<NavShellViewModel>;

public sealed partial class NavHomeView : RunicView<NavHomeViewModel>;

public sealed partial class NavEditorView : RunicView<NavEditorViewModel>;

/// <summary>Content of the shell's main region.</summary>
public interface INavPageViewModel : INotifyPropertyChanged
{
    /// <summary>The page title.</summary>
    string Title { get; }
}

public sealed class NavShellViewModel : INotifyPropertyChanged
{
    public NavShellViewModel(RunicNavigator navigator, INavPageViewModel? home = null) =>
        Main = navigator.CreateRegion<INavPageViewModel>(this, home is null ? null : NavigationTarget.Borrow(home));

    /// <summary>The main content; the navigator changes it.</summary>
    public NavigationRegion<INavPageViewModel> Main { get; }

    public event PropertyChangedEventHandler? PropertyChanged { add { } remove { } }
}

public sealed class NavHomeViewModel : INavPageViewModel, INavigationDepartureGuard, INavigationArrived
{
    public string Title => "home";

    internal Func<CancellationToken, ValueTask<bool>>? Guard { get; set; }

    // Runs when the home page becomes current again, like a page that reloads its data.
    internal Func<ValueTask>? Activate { get; set; }

    public ValueTask<bool> CanDepartAsync(NavigationDeparture departure, CancellationToken cancellationToken) =>
        Guard?.Invoke(cancellationToken) ?? ValueTask.FromResult(true);

    ValueTask INavigationArrived.OnArrivedAsync(NavigationEntryContext entry, NavigationArrival arrival, CancellationToken cancellationToken) =>
        Activate?.Invoke() ?? ValueTask.CompletedTask;

    public event PropertyChangedEventHandler? PropertyChanged { add { } remove { } }
}

public sealed class NavEditorViewModel(string title) : INavPageViewModel, IDisposable
{
    private string _draft = "";

    public string Title { get; } = title;

    public string Draft
    {
        get => _draft;
        set { _draft = value; PropertyChanged?.Invoke(this, new(nameof(Draft))); }
    }

    public int Disposed { get; private set; }

    public void Dispose() => Disposed++;

    public event PropertyChangedEventHandler? PropertyChanged;
}

// A View of an abstract base ViewModel presents its subclasses, which have no
// View of their own; the generator does not warn about them (#407).
public sealed partial class NavLogPageView : RunicView<NavLogPageViewModel>;

public abstract class NavLogPageViewModel : INavPageViewModel
{
    public abstract string Title { get; }

    public event PropertyChangedEventHandler? PropertyChanged { add { } remove { } }
}

public sealed class NavControllerLogViewModel : NavLogPageViewModel
{
    public override string Title => "controller log";
}

internal sealed class NavViewLocator : IRunicViewLocator
{
    public TView Locate<TView, TViewModel>() where TView : class, IRunicView where TViewModel : class =>
        typeof(TView) == typeof(NavHomeView) ? (TView)(object)new NavHomeView()
        : typeof(TView) == typeof(NavEditorView) ? (TView)(object)new NavEditorView()
        : typeof(TView) == typeof(ReactiveNavEditorView) ? (TView)(object)new ReactiveNavEditorView()
        : typeof(TView) == typeof(NavLogPageView) ? (TView)(object)new NavLogPageView()
        : throw new InvalidOperationException($"Unexpected View {typeof(TView).Name}.");
}

// A region page without a View. The generator warns about it (RUNICBRIDGE013,
// suppressed in this project) and presenting it fails with a message that
// names the region and the type.
public sealed class NavOrphanViewModel : INavPageViewModel
{
    public string Title => "orphan";

    public event PropertyChangedEventHandler? PropertyChanged { add { } remove { } }
}
